cards.solution:
class Suhu {
  static jumlah = 0;
  constructor(celsius) {
    this.celsius = celsius;
    Suhu.jumlah++;
  }
  static dariFahrenheit(f) {
    return new Suhu((f - 32) * 5 / 9);
  }
}
const didih = Suhu.dariFahrenheit(212);
const beku = Suhu.dariFahrenheit(32);
console.log(`Celsius: ${didih.celsius}`);
console.log(`Celsius: ${beku.celsius}`);
console.log(`Dibuat: ${Suhu.jumlah}`);
